// Des: Command context: config, paths, state, browser, output, alert
// Flo: find + load config > expand paths > open store > launch Chrome on own profile (or mock page) > connect CDP > emit text
// I/O: process Init + Args (main) > Ctx, Stor, Live (CDP link); text on stdout, alert file + stderr
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const conf = @import("cf-conf-load.zig"); const data = @import("st-stat-data.zig"); const targ = @import("ct-ctrl-args.zig"); const brow = @import("nt-brow-laun.zig"); const cdp = @import("nt-cdpz-sock.zig"); const mock = @import("te-mock-page.zig"); const zsim = @import("te-zsim-page.zig"); const snap = @import("ru-page-snap.zig"); const file = @import("st-stor-file.zig"); const erro = @import("er-erro-type.zig"); const priv = @import("ru-safe-priv.zig"); const lck = @import("st-lock-main.zig"); const dial = @import("ru-page-dial.zig"); const book = @import("ut-acct-book.zig"); const acctm = @import("ru-acct-main.zig");
const CF = .{ .file = "aa-conf-main.json", .dbnm = "za-stat.db", .alrt = "za-alert.txt", .wait = 30000, .zalo = "chat.zalo.me" };
pub const Ctx = struct { init: std.process.Init, allo: std.mem.Allocator, iozz: std.Io, cfg: conf.Conf, args: targ.Args, stat: []const u8, prof: []const u8, acct: []const u8 = "main", book: book.Book = .{ .main = "main", .accs = &.{.{}}, .filez = false }, secd: []const u8 = "", feed: []const u8 = "" };
pub const Live = struct { gpaz: std.mem.Allocator, bro: brow.Brow, conn: *cdp.Conn, iozz: std.Io, lockp: []const u8, pub fn close(self: *Live) void { self.conn.close(); self.bro.stop(); lck.release(self.iozz, self.lockp); } };
pub fn confFind(allo: std.mem.Allocator, iozz: std.Io, args: targ.Args) !conf.Conf { if (args.conf.len > 0) return conf.confLoad(allo, iozz, args.conf); const dirz = std.process.executableDirPathAlloc(iozz, allo) catch "."; const path = try std.fs.path.join(allo, &.{ dirz, CF.file }); if (file.fileHas(iozz, path)) return conf.confLoad(allo, iozz, path); return conf.confLoad(allo, iozz, CF.file); }
pub fn make(init: std.process.Init, args: targ.Args) !Ctx { const allo = init.arena.allocator(); var cfg = try confFind(allo, init.io, args); const home = init.environ_map.get("USERPROFILE") orelse init.environ_map.get("HOME") orelse "."; const root = try conf.pathHome(allo, home, conf.dataRoot(cfg, builtin.os.tag == .windows)); const secd = try conf.pathHome(allo, home, cfg.secr_loca_main); const bk = try book.loadBook(allo, init.io, secd, cfg.acct_maxx_coun); const id = if (args.acct.len > 0 and !std.mem.eql(u8, args.acct, "all")) args.acct else bk.main; if (!book.idOk(id)) return error.BadUsage; const acc = book.pick(bk, id) orelse return error.BadUsage; cfg = acctm.applyScal(cfg, acc.scal); if (std.mem.eql(u8, acc.lang, "vi") or std.mem.eql(u8, acc.lang, "en")) cfg.lang_main_code = acc.lang; erro.viet = std.mem.eql(u8, cfg.lang_main_code, "vi"); if (!args.quiet()) _ = acctm.migrate(allo, init.io, root) catch false; return .{ .init = init, .allo = allo, .iozz = init.io, .cfg = cfg, .args = args, .stat = try std.fs.path.join(allo, &.{ root, "acct", id, "stat" }), .prof = try std.fs.path.join(allo, &.{ root, "acct", id, "prof" }), .acct = id, .book = bk, .secd = secd, .feed = conf.pathHome(allo, home, if (builtin.os.tag == .windows) cfg.feed_dirz_wind else cfg.feed_dirz_unix) catch "" }; }
pub fn emit(ctx: *Ctx, text: []const u8) !void { if (ctx.args.sink) |sink| { try sink.appendSlice(ctx.allo, text); return; } try std.Io.File.stdout().writeStreamingAll(ctx.iozz, text); }
pub fn emitf(ctx: *Ctx, comptime fmt: []const u8, args: anytype) !void { try emit(ctx, try std.fmt.allocPrint(ctx.allo, fmt, args)); }
pub fn openStor(ctx: *Ctx) !data.Stor { try std.Io.Dir.cwd().createDirPath(ctx.iozz, ctx.stat); try std.Io.Dir.cwd().createDirPath(ctx.iozz, ctx.prof); if (std.fs.path.dirname(ctx.stat)) |root| { const who = priv.ownerId(ctx.allo, ctx.iozz, ctx.init.environ_map.get("SystemRoot") orelse "") catch ""; if (who.len > 0 or (@import("builtin").os.tag != .windows)) priv.ownerOnly(ctx.allo, ctx.iozz, root, who) catch {}; } const path = try std.fmt.allocPrintSentinel(ctx.allo, "{s}{c}{s}", .{ ctx.stat, std.fs.path.sep, CF.dbnm }, 0); return data.Stor.open(ctx.allo, path); }
pub fn openRead(ctx: *Ctx) !data.Stor { const path = try std.fmt.allocPrintSentinel(ctx.allo, "{s}{c}{s}", .{ ctx.stat, std.fs.path.sep, CF.dbnm }, 0); if (!file.fileHas(ctx.iozz, path)) return data.Stor.open(ctx.allo, ":memory:"); return data.Stor.open(ctx.allo, path); }
pub fn nowMs(ctx: *Ctx) i64 { return @intCast(std.Io.Clock.real.now(ctx.iozz).toMilliseconds()); }
pub fn alert(ctx: *Ctx, msg0: []const u8) void { const msg = if (std.mem.eql(u8, ctx.acct, "main")) msg0 else (std.fmt.allocPrint(ctx.allo, "[{s}] {s}", .{ ctx.acct, msg0 }) catch msg0); std.debug.print("ALERT: {s}\n", .{msg}); const path = std.fs.path.join(ctx.allo, &.{ ctx.stat, CF.alrt }) catch return; const body = std.fmt.allocPrint(ctx.allo, "{d} {s}\n", .{ nowMs(ctx), msg }) catch return; file.fileAtom(ctx.allo, ctx.iozz, path, body) catch {}; }
pub fn consentOk(sto: *data.Stor, aren: std.mem.Allocator) bool { const val = sto.metaGet(aren, "tos_ok") catch return false; return val != null and val.?.len > 0; }
fn settle(gpaz: std.mem.Allocator, iozz: std.Io, conn: *cdp.Conn, secs: u32) void { var left: u64 = @as(u64, secs) * 2; while (left > 0) : (left -= 1) { var aren = std.heap.ArenaAllocator.init(gpaz); defer aren.deinit(); const nodes = snap.axSnap(aren.allocator(), conn) catch return; if (nodes.len > 20) break; std.Io.sleep(iozz, .fromMilliseconds(500), .awake) catch return; } }
pub fn openLive(ctx: *Ctx, headed: bool) !Live { if ((ctx.args.mode == .live or ctx.args.mode == .force) and !ctx.args.mock) { var cst = try openStor(ctx); defer cst.close(); if (!consentOk(&cst, ctx.allo)) return error.NoConsent; } const lockp = try std.fs.path.join(ctx.allo, &.{ ctx.stat, "za.lock" }); try lck.acquire(ctx.allo, ctx.iozz, lockp, lck.pidSelf(), nowMs(ctx)); errdefer lck.release(ctx.iozz, lockp); const gpaz = ctx.init.gpa; if (ctx.args.mock) { const mpr = try std.fs.path.join(ctx.allo, &.{ ctx.stat, "mock-prof" }); const page = try zsim.html(ctx.allo); const mok = try mock.start(gpaz, ctx.iozz, mpr, page); return .{ .gpaz = gpaz, .bro = mok.bro, .conn = mok.conn, .iozz = ctx.iozz, .lockp = lockp }; } const exe = (try brow.exeFind(gpaz, ctx.iozz, ctx.cfg.brow_exec_path)) orelse return error.NoBrowser; defer gpaz.free(exe); var bro = try brow.launch(gpaz, ctx.iozz, exe, ctx.prof, ctx.cfg.brow_head_mode and !headed, .{ .widt = ctx.cfg.brow_wind_widt, .high = ctx.cfg.brow_wind_high, .scal = ctx.cfg.brow_wind_scal, .left = ctx.cfg.brow_wind_left }, CF.wait); errdefer bro.stop(); const path = try brow.pageWs(gpaz, ctx.iozz, bro.port, CF.wait); defer gpaz.free(path); const conn = try cdp.connect(gpaz, ctx.iozz, bro.port, path, CF.wait); errdefer conn.close(); const href = snap.evalStr(ctx.allo, conn, "location.href") catch ""; if (std.mem.find(u8, href, CF.zalo) == null) try snap.navigate(ctx.allo, conn, ctx.cfg.zalo_page_urlz, CF.wait); settle(gpaz, ctx.iozz, conn, ctx.cfg.brow_time_secs); dial.denyPerms(ctx.allo, conn); return .{ .gpaz = gpaz, .bro = bro, .conn = conn, .iozz = ctx.iozz, .lockp = lockp }; }
